$EvidenceDir = Join-Path $RepoRoot 'docs/evidence/recovery'
$BrowserDir = Join-Path $EvidenceDir 'screenshots/r92-workflow-advanced-node-publish-impact'
$ResultPath = Join-Path $EvidenceDir 'r92-workflow-advanced-node-publish-impact-result.json'
