function Invoke-Api {
    param([string]$Method, [string]$Path, [object]$Body = $null, [hashtable]$Headers = @{})
    $jsonBody = if ($null -eq $Body) { $null } else { $Body | ConvertTo-Json -Depth 100 -Compress }
    try {
        if ($null -eq $jsonBody) { $response = Invoke-RestMethod -Method $Method -Uri "$BaseUrl$Path" -Headers $Headers -TimeoutSec 60 }
        else { $response = Invoke-RestMethod -Method $Method -Uri "$BaseUrl$Path" -Headers $Headers -ContentType 'application/json; charset=utf-8' -Body $jsonBody -TimeoutSec 60 }
    } catch {
        $status = 0; $body = $_.Exception.Message
        if ($_.Exception.Response) { $status = [int]$_.Exception.Response.StatusCode; try { $body = ([System.IO.StreamReader]::new($_.Exception.Response.GetResponseStream())).ReadToEnd() } catch {} }
        throw "API failed: $Method $Path -> HTTP $status $body"
    }
    if ($response.code -ne 'SUCCESS') { throw "API failed: $Method $Path -> $($response | ConvertTo-Json -Depth 30 -Compress)" }
    return $response.data
}
function Invoke-ExpectedDenied { param([string]$Method, [string]$Path, [object]$Body = $null, [hashtable]$Headers = @{}) try { $null = Invoke-Api -Method $Method -Path $Path -Body $Body -Headers $Headers } catch { if ($_.Exception.Message -match 'HTTP 401|HTTP 403|PERMISSION_DENIED|没有系统后台管理权限|权限|无权') { return @{ status = 'DENIED'; path = $Path; detail = $_.Exception.Message } }; throw }; throw "Expected denied request but it succeeded: $Method $Path" }
function Add-Check([System.Collections.Generic.List[object]]$Checks, [string]$Area, [string]$Name, [bool]$Passed, [string]$Detail) { $Checks.Add([pscustomobject]@{ area = $Area; name = $Name; passed = $Passed; detail = $Detail }) | Out-Null }
function Read-DeployedAssetText { try { $index = (Invoke-WebRequest -Uri "$BaseUrl/" -UseBasicParsing -TimeoutSec 30).Content; $assetMatches = [regex]::Matches($index, 'src="(?<src>/assets/[^""<>]+\.js)"'); if ($assetMatches.Count -eq 0) { return '' }; $texts = New-Object System.Collections.Generic.List[string]; foreach ($match in $assetMatches) { $texts.Add((Invoke-WebRequest -Uri "$BaseUrl$($match.Groups['src'].Value)" -UseBasicParsing -TimeoutSec 30).Content) | Out-Null }; return ($texts -join "`n") } catch { return '' } }
function Get-FreeTcpPort { $listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 0); $listener.Start(); $port = $listener.LocalEndpoint.Port; $listener.Stop(); return $port }
function Find-Chrome { $paths = @("$env:ProgramFiles\Google\Chrome\Application\chrome.exe", "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe", "$env:LocalAppData\Google\Chrome\Application\chrome.exe", "$env:ProgramFiles\Microsoft\Edge\Application\msedge.exe", "${env:ProgramFiles(x86)}\Microsoft\Edge\Application\msedge.exe"); foreach ($candidate in $paths) { if ($candidate -and (Test-Path -LiteralPath $candidate)) { return $candidate } }; throw 'Chrome or Edge executable was not found.' }
function Node { param([string]$Key, [string]$Type, [string]$Name, [int]$X, [int]$Y, [object]$Payload, [bool]$Runtime = $true) return @{ nodeKey = $Key; nodeType = $Type; nodeName = $Name; position = @{ x = $X; y = $Y; width = 180; height = 72 }; propertyPayload = $Payload; status = 1; runtimeExecutable = $Runtime } }
function Edge { param([string]$Key, [string]$Source, [string]$Target, [string]$Label, [object]$Condition = $null) return @{ edgeKey = $Key; sourceNodeKey = $Source; targetNodeKey = $Target; branchLabel = $Label; conditionPayload = $Condition } }
function New-R92Canvas { return @{ nodes = @((Node 'node_r92_approval' 'approval' 'R92 Approval' 80 150 @{ approvalType = 'OR_SIGN'; assigneeType = 'ROLE'; assigneeIds = @('role_flow_approver'); allowTransfer = $true; allowReject = $true; reasonRequired = $true }),(Node 'node_r92_condition' 'condition' 'R92 Amount Condition' 320 150 @{ ruleMode = 'FIRST_MATCH'; defaultBranchLabel = 'default'; unmatchedPolicy = 'FOLLOW_DEFAULT_BRANCH' }),(Node 'node_r92_external_api' 'external_api' 'R92 External API' 560 70 @{ appId = 'openapi_r92_app'; endpointCode = 'notify_external_system'; method = 'POST'; timeoutMs = 3000; retryPolicy = @{ maxRetries = 2; intervalSeconds = 30 } }),(Node 'node_r92_timer' 'timer' 'R92 Timer' 800 70 @{ timerMode = 'DELAY'; delayMinutes = 30; businessCalendarCode = 'default_workday'; maxTriggerCount = 1 }),(Node 'node_r92_field_update' 'field_update' 'R92 Field Update' 560 230 @{ updateRules = @(@{ fieldCode = 'approvalStatus'; valueExpression = 'APPROVED'; overwritePolicy = 'ALWAYS' }); auditReason = 'R92 publish impact verification' }),(Node 'node_r92_timeout' 'timeout_reminder' 'R92 Timeout Reminder' 800 230 @{ targetNodeKey = 'node_r92_approval'; timeoutMinutes = 60; templateCode = 'tpl_flow_timeout_reminder'; escalateToRoleIds = @('role_flow_admin') } $false),(Node 'node_r92_end' 'end' 'R92 End' 1040 150 @{})); edges = @((Edge 'edge_r92_approval_condition' 'node_r92_approval' 'node_r92_condition' 'approved'),(Edge 'edge_r92_condition_api' 'node_r92_condition' 'node_r92_external_api' 'amount >= 100000' @{ expressionId = 'expr_r92_amount_gte'; fieldCode = 'amount'; operator = 'GTE'; expectedValue = 100000; expressionText = 'amount GTE 100000' }),(Edge 'edge_r92_api_timer' 'node_r92_external_api' 'node_r92_timer' 'api success'),(Edge 'edge_r92_timer_end' 'node_r92_timer' 'node_r92_end' 'timer reached'),(Edge 'edge_r92_condition_field' 'node_r92_condition' 'node_r92_field_update' 'amount < 100000' @{ expressionId = 'expr_r92_amount_lt'; fieldCode = 'amount'; operator = 'LT'; expectedValue = 100000; expressionText = 'amount LT 100000' }),(Edge 'edge_r92_field_timeout' 'node_r92_field_update' 'node_r92_timeout' 'write back'),(Edge 'edge_r92_timeout_end' 'node_r92_timeout' 'node_r92_end' 'reminded')) } }

$checks = [System.Collections.Generic.List[object]]::new(); $stamp = Get-Date -Format 'yyyyMMddHHmmss'; $password = 'Aa123456!'; $adminLoginName = "r92_admin_$stamp"; $normalLoginName = "r92_normal_$stamp"; $systemId = ''; $moduleId = ''; $flowId = ''; $status = 'PASS'; $errorMessage = $null; $chromeProcess = $null; $chromeProfile = $null; $warningCodes = @(); $impactTypes = @(); $simHighTypes = @(); $simLowTypes = @(); $published = @{}; $r73Result = $null
