    $normalReg = Invoke-Api -Method Post -Path '/api/v1/auth/register-with-system' -Body @{ accountName = $normalLoginName; mobile = "138$($stamp.Substring($stamp.Length - 8))"; email = "$normalLoginName@example.test"; password = $password; systemName = "R92 Normal Owned $stamp"; systemCode = "r92_normal_$stamp"; tenantMode = 1; templateCode = 'blank' }; $normalHeaders = @{ Authorization = "Bearer $($normalReg.accessToken)" }
    $group = Invoke-Api -Method Post -Path "/api/v1/systems/$systemId/module-groups" -Headers $adminHeaders -Body @{ name = "R92 Flow Group $stamp"; sort = 10; visibleRoleIds = @(); publishStatus = 'DRAFT' }
    $module = Invoke-Api -Method Post -Path "/api/v1/systems/$systemId/modules" -Headers $adminHeaders -Body @{ groupId = [string]$group.groupId; moduleCode = "r92_flow_case_$stamp"; name = "R92 Flow Case $stamp"; status = 1; description = 'R92 workflow advanced node module' }; $moduleId = [string]$module.moduleId
    $library = Invoke-Api -Method Get -Path "/api/v1/systems/$systemId/flows/node-library" -Headers $adminHeaders; $libraryTypes = @($library | ForEach-Object { [string]$_.nodeType }); $requiredLibrary = @('approval','condition','field_update','external_api','timer','timeout_reminder','end'); $missingLibrary = @($requiredLibrary | Where-Object { $libraryTypes -notcontains $_ }); Add-Check $checks 'api-library' 'advanced node library exposes required node types' ($missingLibrary.Count -eq 0) "types=$($libraryTypes -join ',') missing=$($missingLibrary -join ',')"
