    $canvas = New-R92Canvas; $savedFlow = Invoke-Api -Method Put -Path "/api/v1/systems/$systemId/flows/$flowId/canvas" -Headers $adminHeaders -Body $canvas; $readCanvas = Invoke-Api -Method Get -Path "/api/v1/systems/$systemId/flows/$flowId/canvas" -Headers $adminHeaders; $readTypes = @($readCanvas.nodes | ForEach-Object { [string]$_.nodeType }); $missingReadTypes = @($requiredLibrary | Where-Object { $readTypes -notcontains $_ }); Add-Check $checks 'api-canvas' 'advanced canvas save/readback preserves node types and edges' (($missingReadTypes.Count -eq 0) -and (@($readCanvas.edges).Count -ge 7)) "nodes=$($readTypes -join ',') edges=$(@($readCanvas.edges).Count)"
