    $normalDetailDenied = Invoke-ExpectedDenied -Method Get -Path "/api/v1/systems/$systemId/flows/$flowId" -Headers $normalHeaders; $normalCanvasDenied = Invoke-ExpectedDenied -Method Put -Path "/api/v1/systems/$systemId/flows/$flowId/canvas" -Headers $normalHeaders -Body $canvas; $normalCheckDenied = Invoke-ExpectedDenied -Method Post -Path "/api/v1/systems/$systemId/flows/$flowId/publish-check" -Headers $normalHeaders -Body @{ reason = 'forbidden'; idempotencyKey = "r92-forbidden-$stamp" }; Add-Check $checks 'permission' 'normal member cannot read mutate or publish-check target system flow admin APIs' (($normalDetailDenied.status -eq 'DENIED') -and ($normalCanvasDenied.status -eq 'DENIED') -and ($normalCheckDenied.status -eq 'DENIED')) "detail=$($normalDetailDenied.status) canvas=$($normalCanvasDenied.status) check=$($normalCheckDenied.status)"
    $sourceAdmin = Get-Content -Raw -Encoding UTF8 (Join-Path $RepoRoot 'frontend/src/features/system-admin/systemAdmin.ts'); $sourceFlow = Get-Content -Raw -Encoding UTF8 (Join-Path $RepoRoot 'backend/examine-flow/src/main/java/com/unique/examine/flow/manage/definition/FlowDefinitionService.java'); $deployedAssetText = Read-DeployedAssetText; $sourceMarkers = @('r92WorkflowDesigner','r92AdvancedNodeLibrary','r92PublishImpactSummary','createAdvancedFlowPreset','W_TIMER_SCHEDULE','WRITE_BACK_FIELD'); $deployedMarkers = @('r92WorkflowDesigner','r92AdvancedNodeLibrary','r92PublishImpactSummary','r92AdvancedPresetButton'); $missingSourceMarkers = @($sourceMarkers | Where-Object { $sourceAdmin -notmatch [regex]::Escape($_) -and $sourceFlow -notmatch [regex]::Escape($_) }); $missingDeployedMarkers = @($deployedMarkers | Where-Object { $deployedAssetText -notmatch [regex]::Escape($_) }); Add-Check $checks 'source' 'R92 source markers exist in frontend and flow service' ($missingSourceMarkers.Count -eq 0) "missing=$($missingSourceMarkers -join ',')"; Add-Check $checks 'deployed' 'deployed asset contains R92 designer markers' (($deployedAssetText.Length -gt 0) -and ($missingDeployedMarkers.Count -eq 0)) "assetLength=$($deployedAssetText.Length) missing=$($missingDeployedMarkers -join ',')"
    $debugPort = Get-FreeTcpPort; $chrome = Find-Chrome; $chromeProfile = Join-Path $BrowserDir "chrome-profile-$stamp"; New-Item -ItemType Directory -Force -Path $chromeProfile | Out-Null; $chromeProcess = Start-Process -FilePath $chrome -ArgumentList @('--headless=new','--disable-gpu','--disable-extensions','--no-sandbox','--no-first-run','--no-default-browser-check','--remote-allow-origins=*',"--remote-debugging-port=$debugPort","--user-data-dir=$chromeProfile",'about:blank') -PassThru -WindowStyle Hidden; $ready = $false; for ($i = 0; $i -lt 50; $i++) { try { Invoke-RestMethod -Uri "http://127.0.0.1:$debugPort/json/version" -TimeoutSec 2 | Out-Null; $ready = $true; break } catch { Start-Sleep -Milliseconds 200 } }; if (-not $ready) { throw 'Chrome DevTools endpoint did not become ready.' }
    $browserOut = Join-Path $BrowserDir 'workflow-advanced-node-browser-audit.json'; $env:R92_BASE_URL = $BaseUrl; $env:R92_CDP_PORT = [string]$debugPort; $env:R92_BROWSER_OUT = $browserOut; $env:R92_SYSTEM_ID = $systemId; $env:R92_FLOW_ID = $flowId; $env:R92_ADMIN_ACCESS_TOKEN = [string]$adminReg.accessToken; $env:R92_ADMIN_REFRESH_TOKEN = [string]$adminReg.refreshToken; $env:R92_ADMIN_ACCOUNT_ID = [string]$adminReg.accountId; $nodeExe = if (Test-Path 'D:\dev\nodejs24\node.exe') { 'D:\dev\nodejs24\node.exe' } else { 'node' }; $nodeOutput = & $nodeExe $BrowserScriptPath 2>&1; if ($LASTEXITCODE -ne 0) { throw "R92 browser audit failed: $nodeOutput" }; $browser = Get-Content -Raw -LiteralPath $browserOut | ConvertFrom-Json; if ($browser.error) { throw "R92 browser audit failed: $($browser.error)" }
    $browserResults = @($browser.results); $desktop = @($browserResults | Where-Object { $_.kind -eq 'admin-desktop-after' }) | Select-Object -First 1; $mobile = @($browserResults | Where-Object { $_.kind -eq 'admin-mobile' }) | Select-Object -First 1; $desktopTypes = @($desktop.nodeTypes); $browserMissingTypes = @($requiredLibrary | Where-Object { $desktopTypes -notcontains $_ }); $browserOverflowCount = @($browserResults | Where-Object { $_.overflowX -gt 2 }).Count; $browserBlockerCount = @($browserResults | Where-Object { $_.blockerText -eq $true }).Count; Add-Check $checks 'browser' 'admin browser exposes advanced library canvas properties publish impact and simulation' ($desktop.designer -and $desktop.advancedPresetButton -and $browserMissingTypes.Count -eq 0 -and $desktop.publishSummary -eq 'true' -and $desktop.publishImpactCount -ge 7 -and $desktop.publishWarningCount -ge 4 -and $desktop.simulationPassed -eq 'true' -and $desktop.simulationStepCount -ge 5) ($desktop | ConvertTo-Json -Depth 20 -Compress); Add-Check $checks 'browser' 'mobile workflow designer remains contained' ($mobile.designer -and $mobile.overflowX -eq 0) ($mobile | ConvertTo-Json -Depth 20 -Compress); Add-Check $checks 'browser' 'R92 browser audit has no overflow or blocker text' (($browserOverflowCount -eq 0) -and ($browserBlockerCount -eq 0)) "overflow=$browserOverflowCount blockers=$browserBlockerCount results=$($browserResults.Count)"
