$failed = @($checks | Where-Object { -not $_.passed }); if ($failed.Count -gt 0) { $status = 'FAIL' }
$result = [ordered]@{ status = $status; task = 'REC-P0-092'; generatedAt = (Get-Date).ToString('o'); baseUrl = $BaseUrl; userSignoff = $false; systemId = $systemId; moduleId = $moduleId; flowId = $flowId; normalLoginName = $normalLoginName; checks = $checks; warningCodes = $warningCodes; impactTypes = $impactTypes; simulationHighNodeTypes = $simHighTypes; simulationLowNodeTypes = $simLowTypes; publishedVersion = $published.version; browserAudit = 'docs/evidence/recovery/screenshots/r92-workflow-advanced-node-publish-impact/workflow-advanced-node-browser-audit.json'; runtimeChildEvidence = 'docs/evidence/recovery/r73-workflow-todo-message-error-state-residual-result.json'; error = $errorMessage }
$result | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $ResultPath -Encoding UTF8
$summary = @('# R92 Workflow Advanced Node Publish Impact Evidence','',"- Status: $status","- BaseUrl: $BaseUrl","- System: $systemId","- Flow: $flowId","- Advanced warnings: $(@($warningCodes) -join ', ')","- Impact refs: $(@($impactTypes) -join ', ')","- Simulation high path: $(@($simHighTypes) -join ' -> ')","- Simulation low path: $(@($simLowTypes) -join ' -> ')","- Published version: $($published.version)","- Browser audit: docs/evidence/recovery/screenshots/r92-workflow-advanced-node-publish-impact/workflow-advanced-node-browser-audit.json","- Runtime child evidence: docs/evidence/recovery/r73-workflow-todo-message-error-state-residual-result.json","- User signoff: false (engineering evidence only)",'','## Checks')
foreach ($check in $checks) { $summary += "- [$($check.passed)] $($check.area) / $($check.name): $($check.detail)" }; if ($errorMessage) { $summary += "`nFatal: $errorMessage" }; $summary -join "`n" | Set-Content -LiteralPath $SummaryPath -Encoding UTF8
